contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function with parameters controlling Ether sent and data for sendMoney
    function run(uint amount, address target, uint sendValue, bytes calldata data) public payable {
        require(address(this).balance >= amount, "insufficient balance for test send");
        // read before values
        uint beforeCount = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // perform receive by sending amount wei to c
        c.f{value: 0}(/* no-op to satisfy pattern */);
        // Note: We cannot call receive() directly; to trigger receive we must send value with a low-level call
        // Use call from this contract to c by using payable address(c).call{value: amount}("") below
        bool sent = payable(address(c)).call{value: amount}("");

        // capture whether receive reverted (sent == false indicates revert)
        bool receiveReverted = !sent;

        uint afterCount = c.depositsCount();
        uint afterBalance = address(c).balance;

        // Try to call owner-only functions and record whether they revert. These must revert because this contract is not the owner.
        bool withdrawReverted;
        bool withdrawAllReverted;
        bool sendMoneyReverted;

        // withdraw(uint)
        try c.withdraw(sendValue) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        // withdrawAll()
        try c.withdrawAll() {
            withdrawAllReverted = false;
        } catch {
            withdrawAllReverted = true;
        }

        // sendMoney(address,uint,bytes)
        try c.sendMoney(target, sendValue, data) {
            sendMoneyReverted = false;
        } catch {
            sendMoneyReverted = true;
        }

        /* General assertion:
           - If the low-level send that was intended to trigger receive succeeded, then depositsCount increased by exactly 1 and balance increased by amount.
           - If the low-level send reverted, depositsCount and balance did not change.
           - Additionally, all owner-only calls must revert when invoked by this test contract. */
        assert(
            ((receiveReverted && afterCount == beforeCount && afterBalance == beforeBalance)
             || (!receiveReverted && afterCount == beforeCount + 1 && afterBalance == beforeBalance + amount))
            && withdrawReverted && withdrawAllReverted && sendMoneyReverted
        );
    }

    // allow this test contract to receive Ether so it can forward to c
    receive() external payable {}
}

