contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We try calling withdraw and withdrawAll and assert that neither succeeds when called by this contract
    // (InvMutTest is not the owner of C, since C.owner was set to the account that deployed C).
    function run(uint withdrawAmount) public payable {
        require(true);

        // Ensure we have some balance to attempt withdraws if needed
        // We can send Ether to c by calling its receive via a direct call from this test contract.
        // But per constraints, any state-changing call must be a top-level statement.
        if (msg.value > 0) {
            // send Ether to c so that withdraw could in principle transfer something
            // Note: this call will execute C.receive and increment depositsCount.
            c.f{value: msg.value}();
        }

        // Read pre-state observable values
        uint beforeBalance = address(this).balance;
        uint cBalanceBefore = address(c).balance;
        uint depositsBefore = c.depositsCount();

        bool withdrewSucceeded;
        // try withdraw(uint)
        try c.withdraw(withdrawAmount) {
            withdrewSucceeded = true;
        } catch {
            withdrewSucceeded = false;
        }

        bool withdrewAllSucceeded;
        // try withdrawAll()
        try c.withdrawAll() {
            withdrewAllSucceeded = true;
        } catch {
            withdrewAllSucceeded = false;
        }

        // Observables after attempts
        uint cBalanceAfter = address(c).balance;
        uint depositsAfter = c.depositsCount();
        uint afterBalance = address(this).balance;

        // General rule: since InvMutTest is not the owner of c (owner was set when c was deployed),
        // any attempt to call withdraw or withdrawAll from this contract must fail (revert),
        // and thus c's balance and depositsCount cannot decrease as a result of these calls.
        assert(
            // both calls must have reverted
            (withdrewSucceeded == false) && (withdrewAllSucceeded == false)
            // and observable state must not have decreased: c balance unchanged and depositsCount non-decreasing
            && (cBalanceAfter == cBalanceBefore)
            && (depositsAfter >= depositsBefore)
            // and this contract shouldn't gain Ether from c as a result
            && (afterBalance == beforeBalance)
        );
    }

    // fallback to accept Ether if needed
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Try to call withdraw and withdrawAll; ensure both revert and no observable state changes occur.
    function run(uint withdrawAmount) public payable {
        require(true);

        // If msg.value > 0, send Ether to c by invoking its receive via a plain transfer from this contract.
        // Ensure this contract has enough balance to send the amount.
        if (msg.value > 0) {
            require(address(this).balance >= msg.value);
            // send Ether to c which will trigger C.receive and increment depositsCount
            (bool ok, ) = address(c).call{value: msg.value}("");
            // It's acceptable for this to revert only if msg.value > 0 and c.receive reverts, but we don't require it here.
            // We don't catch it; if it reverts the whole run will revert and the checker won't consider this trace.
            require(ok);
        }

        // Read observable pre-state
        uint beforeThis = address(this).balance;
        uint beforeC = address(c).balance;
        uint depositsBefore = c.depositsCount();

        // Attempt withdraw(uint)
        bool withdrawSucceeded;
        try c.withdraw(withdrawAmount) {
            withdrawSucceeded = true;
        } catch {
            withdrawSucceeded = false;
        }

        // Attempt withdrawAll()
        bool withdrawAllSucceeded;
        try c.withdrawAll() {
            withdrawAllSucceeded = true;
        } catch {
            withdrawAllSucceeded = false;
        }

        // Read observable post-state
        uint afterThis = address(this).balance;
        uint afterC = address(c).balance;
        uint depositsAfter = c.depositsCount();

        // General invariant: since this contract is not the owner of c (owner was set when c was deployed),
        // both withdraw calls must have reverted, and no Ether or depositsCount should have been removed from c,
        // nor should this contract have gained Ether from c.
        assert(
            (withdrawSucceeded == false)
            && (withdrawAllSucceeded == false)
            && (afterC == beforeC)
            && (depositsAfter >= depositsBefore)
            && (afterThis == beforeThis)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: target address to send to, value to forward, arbitrary calldata
    function run(address target, uint value, bytes calldata data, uint depositAmount) public payable {
        require(address(this).balance >= value + depositAmount);
        // Optionally fund C first by sending depositAmount Ether to trigger its receive()
        if (depositAmount > 0) {
            // send Ether to c to invoke its receive and increment depositsCount
            (bool ok1, ) = address(c).call{value: depositAmount}("");
            require(ok1);
        }

        // observe pre-state
        uint beforeCbal = address(c).balance;
        uint beforeDeposits = c.depositsCount();

        // attempt sendMoney and record whether it reverted
        bool reverted;
        try c.sendMoney(target, value, data) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe post-state
        uint afterCbal = address(c).balance;
        uint afterDeposits = c.depositsCount();

        // General rule: if sendMoney did not revert, then only C's balance may have decreased by exactly `value` (sent out);
        // depositsCount must not decrease. If it reverted, neither balance nor depositsCount should decrease.
        // Because sendMoney is protected by onlyOwner, in practice non-owner calls will revert, but the rule allows both outcomes
        // and enforces preservation of depositsCount and consistent balance change magnitude.
        assert(
            (reverted && afterCbal == beforeCbal && afterDeposits >= beforeDeposits)
            || (!reverted && (beforeDeposits <= afterDeposits) && (beforeCbal >= afterCbal) && (beforeCbal - afterCbal == value))
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: target address to send to, value to forward, arbitrary calldata, optional deposit to fund C first
    function run(address target, uint value, bytes calldata data, uint depositAmount) public payable {
        require(address(this).balance >= value + depositAmount);

        // Optionally fund C first by sending depositAmount Ether to trigger its receive()
        if (depositAmount > 0) {
            // top-level state-changing call to C via low-level transfer to its address
            (bool okFund, ) = address(c).call{value: depositAmount}("");
            require(okFund);
        }

        // observe pre-state (view calls only)
        uint beforeCbal = address(c).balance;
        uint beforeDeposits = c.depositsCount();

        // attempt sendMoney as a top-level state-changing call and capture revert via try/catch
        bool reverted;
        try c.sendMoney(target, value, data) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe post-state
        uint afterCbal = address(c).balance;
        uint afterDeposits = c.depositsCount();

        // General invariant:
        // - depositsCount must never decrease
        // - if call reverted, neither C's balance nor depositsCount change
        // - if call did not revert, C's balance may decrease but by at most `value` (cannot send out more than requested)
        assert(
            afterDeposits >= beforeDeposits
            && (reverted ? (afterCbal == beforeCbal && afterDeposits == beforeDeposits)
                         : (beforeCbal >= afterCbal && beforeCbal - afterCbal <= value && afterDeposits >= beforeDeposits))
        );
    }

    // receive to accept refunds/transfers when testing target behaviors
    receive() external payable {}
}

