contract InvMutTest {
    C c;
    address deployer;
    constructor(C _c) { c = _c; deployer = address(_c); }

    // We will attempt a withdraw from this contract (which is NOT the owner) and check it reverts and balance unchanged.
    // Parameters: amount to deposit into c (so c has balance) and withdraw amount to attempt.
    function run(uint depositAmount, uint withdrawAmount) public payable {
        require(address(this).balance >= depositAmount, "insufficient balance for deposit");
        // deposit Ether into c by sending to its receive() via plain call
        // depositsCount increments require the addition check; we just ensure depositAmount can be zero too.
        c.f{value: depositAmount}();

        // read balance before attempted withdraw
        uint before = address(c).balance;

        bool reverted;
        // attempt withdraw from this contract (msg.sender for c will be this contract), which is NOT the owner
        try c.withdraw(withdrawAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint after = address(c).balance;

        // General rule: if caller is not owner (this contract is not owner), any withdraw call must revert and leave balance unchanged.
        // We express that: reverted is true AND balance unchanged. If somehow this contract is owner, then withdraw may succeed; but
        // in the given deployment model the owner is the original deployer of C, not this test contract, so we assert the non-owner property.
        assert(reverted && after == before);
    }

    // allow this contract to receive Ether so it can deposit to c
    receive() external payable {}
}

