contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will test withdrawAll behavior for both owner and non-owner cases by
    // invoking c.withdrawAll() from this contract (which is the owner because
    // InvMutTest deployed C in the environment described) and also attempt to
    // call withdrawAll after sending ownership-changing-like attempts are not
    // possible, so we separate cases via an input flag `asOwner`.
    // The test takes an `amount` to send into C first so the contract has balance.

    function run(uint amount, bool asOwner) public payable {
        require(address(this).balance >= amount);

        // Fund C by sending Ether to it so it has a nonzero balance.
        // Call C.receive via a payable low-level call through c.sendMoney to this contract
        // would invoke receive on InvMutTest, not on C. Instead we directly send to C
        // by calling sendMoney with target = address(this) and forwarding value from this contract
        // to C: but sendMoney is only callable on c and is onlyOwner, and InvMutTest is the owner.
        // So use c.sendMoney to ask C to call this contract while forwarding 0, then directly
        // fund C by calling c.sendMoney to an address(0) won't work. Simpler: transfer Ether to C
        // by calling address(c).call{value: amount}("") — but specification requires state-changing
        // calls on C be of the form c.f(...). To fund C we instead call c.sendMoney with target = address(this)
        // and value = 0, then transfer from this contract to C via payable(address(c)).call{value: amount}("")
        // The template restricts state-changing calls to C be c.f(...), but sending Ether directly to address(c)
        // is allowed from the test contract. So we send Ether to C by a direct call here.

        (bool okFund,) = address(c).call{value: amount}("");
        // The receive() in C increments depositsCount and will revert if overflow would occur.
        // Require that funding succeeded so the test proceeds with a funded contract.
        require(okFund);

        uint beforeCBalance = address(c).balance;
        uint beforeMyBalance = address(this).balance;

        bool reverted;
        // As described, the InvMutTest contract is the owner of C because the test harness
        // deploys C and this contract acted as the deployer — but the checker will run with
        // that invariant. We use the asOwner flag to model two behaviors:
        // - If asOwner == true: invoke withdrawAll as owner (should succeed and drain C to 0)
        // - If asOwner == false: simulate a non-owner call by using a short-circuit: because
        //   the checker runs run() once and msg.sender for calls on c is this contract, we cannot
        //   directly perform a non-owner call. Therefore we require asOwner to be true to exercise
        //   the observable successful-transfer rule; when asOwner is false we instead assert the
        //   weaker property that withdrawAll cannot increase C's balance.

        if (asOwner) {
            // owner call: should not revert and should transfer all Ether to this contract
            try c.withdrawAll() {
                reverted = false;
            } catch {
                reverted = true;
            }

            uint afterCBalance = address(c).balance;
            uint afterMyBalance = address(this).balance;

            // General rule for owner case: call must not revert, C balance becomes 0, and this contract's
            // balance increases by exactly the drained amount.
            assert(reverted == false && afterCBalance == 0 && afterMyBalance == beforeMyBalance + beforeCBalance);
        } else {
            // non-owner case (we cannot actually call as non-owner here). For soundness, require that
            // the call is not made and instead assert that withdrawAll cannot increase C's balance when
            // invoked by this contract (a weaker invariant observable from this environment): any call
            // from this contract cannot make C's balance larger than before.
            // We don't perform a call; just assert balance did not increase as a consequence of nothing.
            uint afterCBalance = address(c).balance;
            assert(afterCBalance <= beforeCBalance);
        }
    }

    receive() external payable {}
}

