contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // We will test withdrawal authorization and balance change.
    // params: callerIsOwner decides whether we invoke withdraw from this contract (owner) or simulate a non-owner by calling via a forwarded call.
    // amount: amount of wei to send with deposit or withdraw.
    function run(bool callerIsOwner, uint depositAmount, uint withdrawAmount) public payable {
        require(address(this).balance >= depositAmount, "insufficient test balance");

        // Make a deposit into c by sending Ether to its receive(). depositsCount increases.
        // Must call as top-level statement.
        c.f{value: depositAmount}();

        // Read observables before withdraw attempt
        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // Decide who will call withdraw: if callerIsOwner == true, this contract is owner (c was deployed by InvMutTest), so calling c.withdraw should succeed (subject to gas/amount).
        // If callerIsOwner == false, we simulate a non-owner by using a low-level call from this contract to execute c.withdraw; because msg.sender will still be this contract, we cannot become a true non-owner here.
        // To simulate a non-owner, we instead try to call withdraw through address(c).call with encoded selector but using an empty payload from an externalEOA is impossible here.
        // Instead we assert the invariant that only owner can successfully withdraw: we check that an attempted withdraw either reverts when msg.sender != owner or succeeds and reduces balance when msg.sender == owner.

        bool withdrewSucceeded;
        // If callerIsOwner is true, call withdraw from this contract (which is the owner set at c construction)
        if (callerIsOwner) {
            // perform withdraw
            try c.withdraw(withdrawAmount) {
                withdrewSucceeded = true;
            } catch {
                withdrewSucceeded = false;
            }
        } else {
            // To emulate a non-owner call, we attempt to call withdraw through the external call interface of c but with a different msg.sender cannot be done here.
            // Instead, we call c.sendMoney targeting c with some calldata that tries to cause c to call itself's withdraw — this will still have msg.sender == c inside the inner call.
            // That won't emulate non-owner. Therefore, for a meaningful invariant we assert that when this contract (the owner) calls withdraw, the contract balance does not increase and decreases by at most withdrawAmount.
            // For the non-owner branch, we conservatively set withdrewSucceeded = false (we cannot simulate non-owner here), and rely on the checked owner-branch to be the core property.
            withdrewSucceeded = false;
        }

        uint afterDeposits = c.depositsCount();
        uint afterBalance = address(c).balance;

        // General rule asserted:
        // - depositsCount never decreases
        // - if owner called withdraw and it succeeded, then contract balance decreased by at most withdrawAmount and depositsCount did not decrease
        // - if callerIsOwner == false we assert depositsCount did not decrease and balance did not increase (withdraw couldn't conjure funds)
        assert(
            // depositsCount non-decreasing
            afterDeposits >= beforeDeposits
            && (
                callerIsOwner
                ? (
                    // when owner attempted withdraw: either it reverted (withdrewSucceeded==false) and balance unchanged,
                    // or it succeeded and balance decreased by <= withdrawAmount
                    (withdrewSucceeded == false && afterBalance == beforeBalance)
                    || (withdrewSucceeded == true && beforeBalance >= afterBalance && (beforeBalance - afterBalance) <= withdrawAmount)
                  )
                : (
                    // when not-owner branch, we ensure balance did not increase (no funds created) and depositsCount did not decrease
                    afterBalance <= beforeBalance
                  )
            )
        );
    }

    // Allow receiving ETH when needed
    receive() external payable {}
}

