    // We will test two behaviors using parameters:
    // - Sending Ether to c via its receive() by invoking c with value `sendAmt`.
    // - Then calling withdrawAll() as the owner (this contract is the owner) and observe balances and depositsCount.
    function run(uint sendAmt) public payable {
        require(address(this).balance >= sendAmt);

        // Read before-values
        uint beforeCount = c.depositsCount();
        uint beforeBalance = address(c).balance;
        uint myBefore = address(this).balance;

        // Perform the deposit by calling the contract's receive via a plain value transfer
        // This is a state-changing call on c and must be top-level
        c.sendMoney(address(0), 0, ""); // harmless non-owner call to exercise call site (doesn't change state)

        // Actually send Ether to c to trigger receive()
        // Use low-level call from this contract to c to invoke receive
        (bool ok,) = address(c).call{value: sendAmt}("");
        bool depositReverted = !ok;

        // Read after-values
        uint afterCount = c.depositsCount();
        uint afterBalance = address(c).balance;
        uint myAfter = address(this).balance;

        // Now try withdrawAll as owner (this contract is the owner since it deployed c)
        bool withdrewReverted;
        try c.withdrawAll() {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        uint finalCount = c.depositsCount();
        uint finalBalance = address(c).balance;
        uint myFinal = address(this).balance;

        // General rule (single assert):
        // If the deposit call did not revert then depositsCount increased by exactly 1 and contract balance increased by sendAmt;
        // then calling withdrawAll must (if it does not revert) transfer all contract balance to this contract leaving contract balance 0 and depositsCount unchanged by withdrawAll.
        assert(
            (
                depositReverted
                ? (
                    // if deposit reverted: no change in count and no change in balance from before to after
                    afterCount == beforeCount && afterBalance == beforeBalance
                )
                : (
                    // if deposit succeeded: count increments by 1 and balance increases by sendAmt
                    afterCount == beforeCount + 1 && afterBalance == beforeBalance + sendAmt
                )
            )
            && (
                // withdrawAll either reverted, in which case no changes, or succeeded transferring all funds out
                (withdrewReverted
                    ? (finalCount == afterCount && finalBalance == afterBalance)
                    : (finalCount == afterCount && finalBalance == 0 && myFinal == myAfter + afterBalance)
                )
            )
        );
    }

    // Allow this contract to receive Ether when withdrawAll transfers to it
    receive() external payable {}
}

