    function run(bool asOwner, uint sendAmount, uint withdrawAmount) public payable {
        require(address(this).balance >= sendAmount);

        // initial observable state
        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // If sendAmount > 0, send Ether to c to increment depositsCount via receive()
        if (sendAmount > 0) {
            // send from this contract to c
            c.f{value: sendAmount}();
        }

        // record state after potential deposit
        uint afterDepositCount = c.depositsCount();
        uint afterDepositBalance = address(c).balance;

        // Now attempt to call withdraw from either owner (this contract) or a non-owner.
        // To simulate a non-owner, we call through a helper contract deployed inline.
        bool withdrewSucceeds;
        bool nonOwnerReverted;
        uint balanceAfterAttempt;

        if (asOwner) {
            // Owner call: should succeed and reduce c's balance by withdrawAmount (up to available balance)
            // Use try/catch to capture revert if any
            try c.withdraw(withdrawAmount) {
                withdrewSucceeds = true;
            } catch {
