            // ignore ok; if false, no deposit occurred
        }

        // Observe state after potential deposit
        uint afterDepositCount = c.depositsCount();
        uint afterDepositBalance = address(c).balance;

        // Now perform the chosen call as THIS contract (which is owner) and record whether it reverted.
        bool callReverted;
        if (callType == 0) {
            try c.withdrawAll() {
                callReverted = false;
            } catch {
                callReverted = true;
            }
        } else if (callType == 1) {
            try c.withdraw(argAmount) {
                callReverted = false;
            } catch {
                callReverted = true;
            }
        } else {
            try c.sendMoney(target, argAmount, data) {
                callReverted = false;
            } catch {
                callReverted = true;
            }
        }

        // Read final observable state
        uint finalDeposits = c.depositsCount();
        uint finalBalance = address(c).balance;

        // Assert a general rule:
        // - If the call reverted, then neither depositsCount nor balance changed compared to afterDeposit.
        // - If the call succeeded (owner call), then the contract's balance did not increase as a result of that call
        //   (owner actions withdraw or send cannot increase contract balance).
        assert( (callReverted && finalDeposits == afterDepositCount && finalBalance == afterDepositBalance)
                || (!callReverted && finalBalance <= afterDepositBalance) );
    }

    receive() external payable {}
}

