    constructor(C _c) { c = _c; other = address(0x1234); }

    // Single public entry taking parameters: amount to send to C and a value to attempt to withdraw
    function run(uint sendAmount, uint withdrawAttempt) public payable {
        require(address(this).balance >= sendAmount);

        // Record initial observable state
        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // Send Ether to c using low-level call with empty data to trigger receive()
        (bool sendSuccess, ) = address(c).call{value: sendAmount}("\x00");
        // Note: using a single zero byte as data still counts as non-empty; to do an empty-data call use ""
        // But solidity string literal "" is not allowed here; use bytes("") equivalent via abi.encodePacked()
        // To adhere to constraints and ensure empty data, re-send with abi.encodePacked() if first sent with data fails
        if (!sendSuccess) {
            // try empty data call
            (sendSuccess, ) = address(c).call{value: sendAmount}(abi.encodePacked());
        }

        // Read state after deposit attempt
        uint afterDeposits = c.depositsCount();
        uint afterBalance = address(c).balance;

        // Determine expected effect: if sendAmount > 0 and call succeeded, depositsCount increments by 1 and balance increases by sendAmount
        bool depositOccurred = (sendAmount > 0) && sendSuccess;

        // Now attempt a withdraw via low-level call as a non-owner (this contract is the owner of C), so use address(c).call from an external address 'other' simulated by encoding a plain call
        // We cannot change msg.sender of this transaction, so simulate a non-owner by using address(c).call which still originates from this contract; however the onlyOwner modifier checks msg.sender == owner, and owner==deployer==this contract, so to test non-owner failure we must call through address(c).call from an EOA — impossible here. Instead, we can assert that low-level call to withdraw from this contract (the owner) succeeds.
        bytes memory payload = abi.encodeWithSignature("withdraw(uint256)", withdrawAttempt);
        (bool ownerWithdrawSuccess, ) = address(c).call(payload);
        uint finalBalance = address(c).balance;
        uint finalDeposits = c.depositsCount();

        // If this contract is owner (it deployed C), ownerWithdrawSuccess should be true and balance should decrease by withdrawAttempt (but capped by available balance) and depositsCount unchanged by withdraw
        // Compute expected withdrawn amount: min(withdrawAttempt, afterBalance)
        uint expectedWithdrawn = withdrawAttempt;
        if (expectedWithdrawn > afterBalance) expectedWithdrawn = afterBalance;

        // Assert the general rule combining deposit and withdraw observations
        assert(
            // deposit behavior: exact increment by 1 and balance increase when a positive amount was accepted
            ((depositOccurred && afterDeposits == beforeDeposits + 1 && afterBalance == beforeBalance + sendAmount)
             || (!depositOccurred && afterDeposits == beforeDeposits && afterBalance == beforeBalance))
            // withdraw behavior for owner: if ownerWithdrawSuccess then final balance decreased by expectedWithdrawn and depositsCount unchanged
            && ((ownerWithdrawSuccess && finalBalance == afterBalance - expectedWithdrawn && finalDeposits == afterDeposits)
                || (!ownerWithdrawSuccess && finalBalance == afterBalance && finalDeposits == afterDeposits))
        );
    }

    receive() external payable {}
}

