            // attempt withdraw as owner
            try c.withdraw(withdrawAmount) {
                withdrawReverted = false;
            } catch {
                withdrawReverted = true;
            }
        } else {
            // simulate a non-owner caller by deploying a small forwarder that attempts the withdraw
            NonOwnerForwarder f = new NonOwnerForwarder(address(c));
            // fund forwarder so it can attempt to call
