            afterDeposits == beforeDeposits
            // if non-owner attempted, then call must have reverted and balance unchanged
            && ( (!isOwnerCall) ? (withdrawReverted && afterBalance == beforeBalance) : true )
            // if owner attempted and it reverted, balance unchanged
