        try c.withdraw(withdrawAmount) {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        // observe after values
        uint afterDeposits = c.depositsCount();
        uint afterBalance = address(c).balance;

        // General rule (single assert):
        // - depositsCount is never changed by withdraw
        // - if withdraw reverted, balance unchanged
        // - if withdraw succeeded, balance decreased by at most withdrawAmount and not increased
        assert(
            afterDeposits == beforeDeposits
            && (withdrewReverted ? (afterBalance == beforeBalance) : (beforeBalance >= afterBalance && (beforeBalance - afterBalance) <= withdrawAmount))
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function takes parameters to try owner and non-owner calls
    function run(address nonOwner, uint sendAmount, uint withdrawAmount) public payable {
        require(true);

        // ensure this contract has enough balance to send to c if requested
        if (sendAmount > 0) {
            require(address(this).balance >= sendAmount);
            // send Ether to C to increase its balance and depositsCount via receive()
            c.f{value: sendAmount}();
        }

        // read observable state before withdraw attempts
        uint beforeBalance = address(c).balance;
        uint beforeDeposits = c.depositsCount();

        // Attempt withdrawAll as owner (this contract is owner since it deployed c)
        bool ownerWithdrawAllReverted;
        try c.withdrawAll() {
            ownerWithdrawAllReverted = false;
        } catch {
            ownerWithdrawAllReverted = true;
        }

        uint afterBalanceOwner = address(c).balance;
        uint afterDepositsOwner = c.depositsCount();

        // Attempt withdraw as non-owner by invoking via low-level call from this contract
        // We simulate a non-owner by constructing calldata for withdraw(uint) and using call with different from not possible here;
        // Instead we check that calling withdraw on c from this contract (the owner) succeeds, and that if another address were to call it it would be restricted.
        // To express the non-owner restriction observationally: deployer of c is owner (this contract), so any change by withdraw must only occur when owner withdraws.

        // For the property we assert: if owner withdrawAll did not revert, then depositsCount did not increase and balance decreased by at most withdrawAmount (withdrawAll withdraws full balance), and ownerWithdrawAllReverted must be false implies afterBalanceOwner <= beforeBalance.

        // Additionally, calling withdraw(uint) as owner should not increase depositsCount and should not increase contract balance.
        bool ownerWithdrawReverted;
        try c.withdraw(withdrawAmount) {
            ownerWithdrawReverted = false;
        } catch {
            ownerWithdrawReverted = true;
        }

        uint afterBalanceFinal = address(c).balance;
        uint afterDepositsFinal = c.depositsCount();

        // General rule asserted for all inputs:
        // - Any successful owner withdraw (either withdrawAll or withdraw) cannot increase depositsCount
        // - Any successful owner withdraw cannot increase c's balance
        assert(
            // if owner withdrawAll succeeded then depositsCount did not increase and balance did not increase
            (ownerWithdrawAllReverted || (afterDepositsOwner == beforeDeposits && afterBalanceOwner <= beforeBalance))
            // and if owner withdraw succeeded then depositsCount did not increase and balance did not increase
            && (ownerWithdrawReverted || (afterDepositsFinal == afterDepositsOwner && afterBalanceFinal <= afterBalanceOwner))
        );
    }

    // allow receiving Ether when c sends back
    receive() external payable {}
}

